let tugas = [];
let idBerikutnya = 1;
const form = document.querySelector("#form-tugas");
const daftar = document.querySelector("#daftar");
const ringkasan = document.querySelector("#ringkasan");

function render() {
  daftar.replaceChildren(...tugas.map((t) => {
    const li = document.createElement("li");
    li.dataset.id = t.id;
    li.classList.toggle("selesai", t.selesai);
    const judul = document.createElement("span");
    judul.textContent = t.judul;
    const centang = document.createElement("button");
    centang.dataset.aksi = "centang";
    centang.textContent = t.selesai ? "Batal" : "Selesai";
    const hapus = document.createElement("button");
    hapus.dataset.aksi = "hapus";
    hapus.textContent = "Hapus";
    li.append(judul, centang, hapus);
    return li;
  }));
  const sisa = tugas.filter((t) => !t.selesai).length;
  ringkasan.textContent = tugas.length === 0 ? "Belum ada tugas" : `${sisa} tugas belum selesai`;
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const judul = form.elements.judul.value.trim();
  if (!judul) return;
  tugas.push({ id: idBerikutnya++, judul, selesai: false });
  form.reset();
  render();
});

daftar.addEventListener("click", (e) => {
  const tombol = e.target.closest("button[data-aksi]");
  if (!tombol) return;
  const id = Number(tombol.closest("li").dataset.id);
  if (tombol.dataset.aksi === "centang") {
    const t = tugas.find((t) => t.id === id);
    t.selesai = !t.selesai;
  } else if (tombol.dataset.aksi === "hapus") {
    tugas = tugas.filter((t) => t.id !== id);
  }
  render();
});

render();
for (const judul of ["Belajar DOM", "Latihan event", "Kerjakan proyek"]) {
  form.elements.judul.value = judul;
  form.requestSubmit();
}
daftar.querySelector('[data-id="1"] [data-aksi="centang"]').click();
daftar.querySelector('[data-id="2"] [data-aksi="hapus"]').click();
console.log(daftar.children.length);
console.log(ringkasan.textContent);

